questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
col(v) := matrix([v[1]],[v[2]]);
/* Design: column vector for a drawn movement, P to Q and its reverse. On every variant at least one component is negative, |a| # |b|, and every diagnostic is distinct. Source: adapted from SMP GCSE Foundation 2, Chapter 15, Section B, B7. */
a: rand_with_prohib(-5,5,[0]);
b0: rand_with_prohib(1,5,[abs(a)]);
b: if a>0 then -b0 else b0*rand([-1,1]);
x0: max(0,-a)+rand(10-abs(a)); y0: max(0,-b)+rand(8-abs(b));
x1: x0+a; y1: y0+b;
ta: col([a,b]); tb: col([-a,-b]);
swp: col([b,a]); absv: col([abs(a),abs(b)]);
tw1: ta+matrix([1],[0]); tw2: tb+matrix([1],[0]);
badm: matrix([q],[1]);
